#!/bin/bash
set -e
cd avbox

echo "=== 添加真搜索功能 ==="

PKG_DIR="app/src/main/java/com/github/tvbox/osc/ui/activity"

# 删除旧的测试页（避免重名冲突）
rm -f "$PKG_DIR/LxMusicSearch.kt"

# 写入搜索 API
echo "" | base64 -d > "$PKG_DIR/LxMusicSearchApi.kt"
echo "LxMusicSearchApi.kt 已写入"

# 写入搜索 Activity
echo "" | base64 -d > "$PKG_DIR/LxMusicSearchActivity.kt"
echo "LxMusicSearchActivity.kt 已写入"

# 更新播放器（支持从歌曲信息获取 URL）
echo "" | base64 -d > "$PKG_DIR/LxPlayerActivity.kt"
echo "LxPlayerActivity.kt 已更新"

echo "" | base64 -d > "$PKG_DIR/LxPlayerManager.kt"
echo "LxPlayerManager.kt 已更新"

# 注册 Activity
MANIFEST="app/src/main/AndroidManifest.xml"
if ! grep -q "LxMusicSearchActivity" "$MANIFEST"; then
    python3 << 'PYEOF2'
manifest = "app/src/main/AndroidManifest.xml"
with open(manifest, 'r', encoding='utf-8') as f:
    c = f.read()
old = '<activity android:name=".ui.activity.LxPlayerActivity"'
new = old + ' />\n        <activity android:name=".ui.activity.LxMusicSearchActivity"'
if old in c and "LxMusicSearchActivity" not in c:
    c = c.replace(old, new)
    with open(manifest, 'w', encoding='utf-8') as f:
        f.write(c)
    print("LxMusicSearchActivity 已注册")
PYEOF2
fi

echo "=== 真搜索功能添加完成 ==="
